		SELECT ('CS-' || TO_CHAR(SYSDATE, 'YYYYMMDD-') || LPAD(SEQ_COURSE_SURVEY_PK.NEXTVAL,6, '0'))
		FROM DUAL

INSERT INTO COURSE_SURVEY
 	  ( ID
 	  , TITLE
 	  , SURVEY_GROUP
 	  , SURVEY_TYPE
 	  , "COUNT"
 	  , SURVEY_SUBJECT
 	  , COURSE_ID)
 SELECT #{id}
 	  , #{title}
 	  , #{surveyGroup}
 	  , #{surveyType}
 	  , COUNT(ID)
 	  , #{surveySubject}
 	  , #{courseId}
  FROM SURVEY
 WHERE "GROUP" = #{surveyGroup}

